     * Uses bash find command with -type f and -name, limits output to 10 files.
     *
     * @param searchDir   the directory to search in (user-provided path)
     * @param filePattern the file pattern to match (supports wildcards like *.txt)
     * @return a newline-separated list of found files, or an error message if the search fails
     */
    public String findFilesWithPattern(String searchDir, String filePattern) {
        // Validate inputs to avoid null or empty strings
        if (searchDir == null || searchDir.trim().isEmpty()) {
            return "Error: search directory must not be null or empty";
        }
        if (filePattern == null || filePattern.trim().isEmpty()) {
            return "Error: file pattern must not be null or empty";
        }

        // Escape single quotes in both parameters to prevent command injection
        String escapedDir = escapeSingleQuotes(searchDir.trim());
        String escapedPattern = escapeSingleQuotes(filePattern.trim());

        // Build the bash command:
        // - find <dir> -type f -name '<pattern>' 2>&1 | head -n 10
        // Redirect stderr to stdout so errors are captured in the output.
        String command = String.format(
            "find '%s' -type f -name '%s' 2>&1 | head -n 10",
            escapedDir,
            escapedPattern
        );

        try {
            // Execute the command using bash -c
            ProcessBuilder processBuilder = new ProcessBuilder("bash", "-c", command);
            processBuilder.redirectErrorStream(true); // combine stdout and stderr
            Process process = processBuilder.start();

            // Read the entire output
            String output;
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(process.getInputStream()))) {
                output = reader.lines().collect(Collectors.joining("\n"));
            }

            // Wait for the process to finish and check exit code
            int exitCode = process.waitFor();

            if (exitCode != 0) {
                // If the command failed, return the output as an error message
                return "Error: search failed with exit code " + exitCode +
                       (output.isEmpty() ? "" : "\n" + output);
            }

            // Return the list of files (may be empty if no matches)
            return output;

        } catch (IOException e) {
            return "Error: I/O exception while executing find command: " + e.getMessage();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return "Error: process was interrupted";
        }
    }

    /**
     * Escapes single quotes in a string for safe use inside single-quoted shell arguments.
     * Replaces each single quote with the sequence: '\'' (end quote, escaped quote, start quote).
     *
     * @param input the string to escape
     * @return the escaped string safe for single-quoted shell arguments
     */
    private String escapeSingleQuotes(String input) {
        // Replace ' with '\'' (quote, backslash, quote, quote)
        return input.replace("'", "'\\''");
    }
}
